#include "gml_frontend.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <ctype.h>

static int is_id0(char c){return isalpha((unsigned char)c)||c=='_';}
static int is_id(char c){return isalnum((unsigned char)c)||c=='_';}
static gml_token tok(gml_token_kind k,const char*s,size_t n){gml_token t={k,s,n,0};return t;}
void gml_lexer_init(gml_lexer*l,const char*s){l->source=s?s:"";l->length=strlen(l->source);l->offset=0;l->line=1;}
int gml_lexer_next(gml_lexer*l,gml_token*out){
 const char*s=l->source; while(l->offset<l->length){char c=s[l->offset]; if(c==' '||c=='\t'||c=='\r'){l->offset++;continue;} if(c=='\n'){l->offset++;l->line++;continue;} if(c=='/'&&l->offset+1<l->length&&s[l->offset+1]=='/'){l->offset+=2;while(l->offset<l->length&&s[l->offset]!='\n')l->offset++;continue;} break;}
 if(l->offset>=l->length){*out=tok(GML_T_EOF,s+l->length,0);return 1;} size_t st=l->offset; char c=s[l->offset++];
 if(isdigit((unsigned char)c)||(c=='.'&&l->offset<l->length&&isdigit((unsigned char)s[l->offset]))){while(l->offset<l->length&&(isdigit((unsigned char)s[l->offset])||s[l->offset]=='.'))l->offset++;*out=tok(GML_T_NUMBER,s+st,l->offset-st);char b[96];size_t n=l->offset-st;if(n>=sizeof b)n=sizeof b-1;memcpy(b,s+st,n);b[n]=0;out->number=strtod(b,0);return 1;}
 if(c=='"'||c=='\''){char q=c;while(l->offset<l->length&&s[l->offset]!=q){if(s[l->offset]=='\\'&&l->offset+1<l->length)l->offset+=2;else l->offset++;}if(l->offset<l->length)l->offset++;*out=tok(GML_T_STRING,s+st+1,l->offset-st-2);return 1;}
 if(is_id0(c)){while(l->offset<l->length&&is_id(s[l->offset]))l->offset++;size_t n=l->offset-st;gml_token_kind k=GML_T_IDENT; if(n==2&&!strncmp(s+st,"if",2))k=GML_T_IF;else if(n==4&&!strncmp(s+st,"else",4))k=GML_T_ELSE;else if(n==3&&!strncmp(s+st,"var",3))k=GML_T_VAR;else if(n==6&&!strncmp(s+st,"return",6))k=GML_T_RETURN;else if(n==4&&!strncmp(s+st,"exit",4))k=GML_T_EXIT;else if(n==5&&!strncmp(s+st,"while",5))k=GML_T_WHILE;else if(n==2&&!strncmp(s+st,"do",2))k=GML_T_DO;else if(n==5&&!strncmp(s+st,"until",5))k=GML_T_UNTIL;else if(n==6&&!strncmp(s+st,"switch",6))k=GML_T_SWITCH;else if(n==4&&!strncmp(s+st,"case",4))k=GML_T_CASE;else if(n==7&&!strncmp(s+st,"default",7))k=GML_T_DEFAULT;else if(n==3&&!strncmp(s+st,"for",3))k=GML_T_FOR;else if(n==6&&!strncmp(s+st,"repeat",6))k=GML_T_REPEAT;else if(n==5&&!strncmp(s+st,"break",5))k=GML_T_BREAK;else if(n==8&&!strncmp(s+st,"continue",8))k=GML_T_CONTINUE;else if(n==4&&!strncmp(s+st,"with",4))k=GML_T_WITH;*out=tok(k,s+st,n);return 1;}
 gml_token_kind k=GML_T_EOF;switch(c){case '+':if(l->offset<l->length&&s[l->offset]=='='){l->offset++;k=GML_T_PLUS_ASSIGN;}else k=GML_T_PLUS;break;case '-':if(l->offset<l->length&&s[l->offset]=='='){l->offset++;k=GML_T_MINUS_ASSIGN;}else k=GML_T_MINUS;break;case '*':if(l->offset<l->length&&s[l->offset]=='='){l->offset++;k=GML_T_STAR_ASSIGN;}else k=GML_T_STAR;break;case '/':if(l->offset<l->length&&s[l->offset]=='='){l->offset++;k=GML_T_SLASH_ASSIGN;}else k=GML_T_SLASH;break;case '%':k=GML_T_PERCENT;break;case '&':if(l->offset<l->length&&s[l->offset]=='&'){l->offset++;k=GML_T_AND;}break;case '|':if(l->offset<l->length&&s[l->offset]=='|'){l->offset++;k=GML_T_OR;}break;case '(':k=GML_T_LPAREN;break;case ')':k=GML_T_RPAREN;break;case '{':k=GML_T_LBRACE;break;case '}':k=GML_T_RBRACE;break;case '[':k=GML_T_LBRACKET;break;case ']':k=GML_T_RBRACKET;break;case ';':k=GML_T_SEMI;break;case ',':k=GML_T_COMMA;break;case '.':k=GML_T_DOT;break;case '?':k=GML_T_QUESTION;break;case ':':k=GML_T_COLON;break;case '=':k=(l->offset<l->length&&s[l->offset]=='=')?(l->offset++,GML_T_EQ):GML_T_ASSIGN;break;case '!':k=(l->offset<l->length&&s[l->offset]=='=')?(l->offset++,GML_T_NE):GML_T_NOT;break;case '<':k=(l->offset<l->length&&s[l->offset]=='=')?(l->offset++,GML_T_LE):GML_T_LT;break;case '>':k=(l->offset<l->length&&s[l->offset]=='=')?(l->offset++,GML_T_GE):GML_T_GT;break;default:k=GML_T_EOF;break;}*out=tok(k,s+st,l->offset-st);return k!=GML_T_EOF||c==0;}

static gml_parser P;static gml_token T;static int next(void){gml_lexer l={(const char*)P.source,P.length,P.offset,P.line};int ok=gml_lexer_next(&l,&T);P.offset=l.offset;P.line=l.line;return ok;}
static void err(const char*m){if(!P.error[0])snprintf(P.error,sizeof P.error,"line %d: %s",P.line,m);}
static gml_ast* node(gml_ast_kind k){gml_ast*n=calloc(1,sizeof *n);if(n)n->kind=k;return n;}
static gml_ast* expr(void);static gml_ast* statement(void); static char* text(gml_token t); static gml_ast* clone_ast(const gml_ast*src){if(!src)return 0;gml_ast*n=node(src->kind);if(!n)return 0;n->op=src->op;n->number=src->number;n->text=src->text?text((gml_token){GML_T_IDENT,src->text,strlen(src->text),0}):0;n->left=clone_ast(src->left);n->right=clone_ast(src->right);n->count=src->count;if(src->count){n->items=calloc(src->count,sizeof(gml_ast*));if(!n->items){gml_ast_free(n);return 0;}for(size_t i=0;i<src->count;i++)n->items[i]=clone_ast(src->items[i]);}return n;}
static int accept(gml_token_kind k){if(T.kind==k){next();return 1;}return 0;}
static char* text(gml_token t){char*s=malloc(t.length+1);if(s){memcpy(s,t.start,t.length);s[t.length]=0;}return s;}
static gml_ast* primary(void){gml_ast*n=0;if(T.kind==GML_T_NUMBER){n=node(GML_AST_NUMBER);n->number=T.number;next();}else if(T.kind==GML_T_STRING){n=node(GML_AST_STRING);n->text=text(T);next();}else if(T.kind==GML_T_IDENT){gml_token id=T;next();n=node(GML_AST_NAME);n->text=text(id);if(accept(GML_T_LPAREN)){n->kind=GML_AST_CALL;n->items=0;n->count=0;if(!accept(GML_T_RPAREN)){for(;;){gml_ast*a=expr();if(!a){gml_ast_free(n);return 0;}gml_ast**v=realloc(n->items,(n->count+1)*sizeof*a);if(!v){gml_ast_free(n);return 0;}n->items=v;n->items[n->count++]=a;if(accept(GML_T_RPAREN))break;if(!accept(GML_T_COMMA)){err("expected comma or )");gml_ast_free(n);return 0;}}}}}else if(accept(GML_T_LPAREN)){n=expr();if(!accept(GML_T_RPAREN))err("expected )");}else{err("expected expression");return 0;}for(;;){if(accept(GML_T_LBRACKET)){gml_ast*i=node(GML_AST_INDEX);i->left=n;i->right=expr();if(!accept(GML_T_RBRACKET))err("expected ]");n=i;continue;}if(accept(GML_T_DOT)){if(T.kind!=GML_T_IDENT){err("expected member name");break;}gml_ast*m=node(GML_AST_MEMBER);m->left=n;m->text=text(T);next();n=m;continue;}break;}return n;}
static gml_ast* unary(void){if(T.kind==GML_T_NOT||T.kind==GML_T_MINUS||T.kind==GML_T_PLUS){int op=T.kind;next();gml_ast*n=node(GML_AST_UNARY);n->op=op;n->left=unary();return n;}return primary();}
static gml_ast* binary(int min){gml_ast*l=unary();while(l){int p=0;switch(T.kind){case GML_T_OR:p=3;break;case GML_T_AND:p=4;break;case GML_T_STAR:case GML_T_SLASH:case GML_T_PERCENT:p=30;break;case GML_T_PLUS:case GML_T_MINUS:p=20;break;case GML_T_EQ:case GML_T_NE:case GML_T_LT:case GML_T_LE:case GML_T_GT:case GML_T_GE:p=10;break;default:p=0;}if(p<min||!p)break;int op=T.kind;next();gml_ast*r=binary(p+1);if(!r){gml_ast_free(l);return 0;}gml_ast*n=node(GML_AST_BINARY);n->op=op;n->left=l;n->right=r;l=n;}return l;}
static gml_ast* expr(void){gml_ast*l=binary(1);if(l&&accept(GML_T_QUESTION)){gml_ast*yes=expr();if(!accept(GML_T_COLON))err("expected : in ternary");gml_ast*no=expr();gml_ast*t=node(GML_AST_TERNARY);if(!t){gml_ast_free(l);gml_ast_free(yes);gml_ast_free(no);return 0;}t->left=l;t->right=yes;t->items=calloc(1,sizeof(gml_ast*));t->count=1;t->items[0]=no;l=t;}if(l&&(l->kind==GML_AST_NAME||l->kind==GML_AST_MEMBER||l->kind==GML_AST_INDEX)&&(T.kind==GML_T_ASSIGN||T.kind==GML_T_PLUS_ASSIGN||T.kind==GML_T_MINUS_ASSIGN||T.kind==GML_T_STAR_ASSIGN||T.kind==GML_T_SLASH_ASSIGN)){int op=T.kind;next();gml_ast*r=expr();if(op!=GML_T_ASSIGN){gml_ast*b=node(GML_AST_BINARY);b->op=(op==GML_T_PLUS_ASSIGN?GML_T_PLUS:op==GML_T_MINUS_ASSIGN?GML_T_MINUS:op==GML_T_STAR_ASSIGN?GML_T_STAR:GML_T_SLASH);b->left=clone_ast(l);b->right=r;r=b;}gml_ast*n=node(GML_AST_ASSIGN);n->left=l;n->right=r;return n;}return l;}
static gml_ast* switch_case_body(void){gml_ast*b=node(GML_AST_BLOCK);if(!b)return 0;while(T.kind!=GML_T_CASE&&T.kind!=GML_T_DEFAULT&&T.kind!=GML_T_RBRACE&&T.kind!=GML_T_EOF){gml_ast*s=statement();if(!s){gml_ast_free(b);return 0;}gml_ast**v=realloc(b->items,(b->count+1)*sizeof*s);if(!v){gml_ast_free(s);gml_ast_free(b);return 0;}b->items=v;b->items[b->count++]=s;}return b;}static gml_ast* statement(void){if(accept(GML_T_VAR)){gml_ast*n=node(GML_AST_EXPR_STMT);n->left=expr();if(!accept(GML_T_SEMI)&&T.kind!=GML_T_EOF)err("expected ;");return n;}if(accept(GML_T_SEMI))return node(GML_AST_EXPR_STMT);if(accept(GML_T_LBRACE)){gml_ast*n=node(GML_AST_BLOCK);while(T.kind!=GML_T_RBRACE&&T.kind!=GML_T_EOF){gml_ast*s=statement();if(!s){gml_ast_free(n);return 0;}gml_ast**v=realloc(n->items,(n->count+1)*sizeof*s);n->items=v;n->items[n->count++]=s;}if(!accept(GML_T_RBRACE))err("expected }");return n;}if(accept(GML_T_IF)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_IF);n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");n->right=statement();if(accept(GML_T_ELSE)){n->items=calloc(1,sizeof(gml_ast*));n->items[0]=statement();n->count=1;}return n;}if(accept(GML_T_WHILE)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_WHILE);n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");n->right=statement();return n;}if(accept(GML_T_SWITCH)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_SWITCH);n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");if(!accept(GML_T_LBRACE))err("expected {");while(T.kind!=GML_T_RBRACE&&T.kind!=GML_T_EOF&&!P.error[0]){gml_ast*c=0;if(accept(GML_T_CASE)){c=node(GML_AST_SWITCH_CASE);c->left=expr();if(!accept(GML_T_COLON))err("expected : after case");}else if(accept(GML_T_DEFAULT)){c=node(GML_AST_SWITCH_CASE);if(!accept(GML_T_COLON))err("expected : after default");}else{err("expected case or default");break;}if(!c){err("out of memory");break;}c->right=switch_case_body();gml_ast**v=realloc(n->items,(n->count+1)*sizeof*c);if(!v){gml_ast_free(c);gml_ast_free(n);err("out of memory");return 0;}n->items=v;n->items[n->count++]=c;}if(!accept(GML_T_RBRACE))err("expected }");return n;}if(accept(GML_T_DO)){gml_ast*n=node(GML_AST_DO_UNTIL);n->right=statement();if(!accept(GML_T_UNTIL))err("expected until");if(!accept(GML_T_LPAREN))err("expected (");n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");accept(GML_T_SEMI);return n;}if(accept(GML_T_FOR)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_FOR);n->items=calloc(4,sizeof(gml_ast*));n->count=4;n->items[0]=expr();if(!accept(GML_T_SEMI))err("expected ;");n->items[1]=expr();if(!accept(GML_T_SEMI))err("expected ;");n->items[2]=expr();if(!accept(GML_T_RPAREN))err("expected )");n->items[3]=statement();return n;}if(accept(GML_T_REPEAT)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_REPEAT);n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");n->right=statement();return n;}if(accept(GML_T_WITH)){if(!accept(GML_T_LPAREN))err("expected (");gml_ast*n=node(GML_AST_WITH);n->left=expr();if(!accept(GML_T_RPAREN))err("expected )");n->right=statement();return n;}if(accept(GML_T_RETURN)){gml_ast*n=node(GML_AST_RETURN);n->left=(T.kind==GML_T_SEMI?0:expr());accept(GML_T_SEMI);return n;}if(accept(GML_T_EXIT)){gml_ast*n=node(GML_AST_EXIT);accept(GML_T_SEMI);return n;}if(accept(GML_T_BREAK)){gml_ast*n=node(GML_AST_BREAK);accept(GML_T_SEMI);return n;}if(accept(GML_T_CONTINUE)){gml_ast*n=node(GML_AST_CONTINUE);accept(GML_T_SEMI);return n;}gml_ast*n=node(GML_AST_EXPR_STMT);n->left=expr();if(!accept(GML_T_SEMI)&&T.kind!=GML_T_EOF)err("expected ;");return n;}
int gml_parse_program(const char*s,gml_ast**out,char*e,size_t cap){if(!out)return 0;*out=0;memset(&P,0,sizeof P);P.source=s?s:"";P.length=strlen(P.source);next();gml_ast*n=node(GML_AST_BLOCK);while(T.kind!=GML_T_EOF&&!P.error[0]){gml_ast*x=statement();if(!x)break;gml_ast**v=realloc(n->items,(n->count+1)*sizeof*x);if(!v){gml_ast_free(n);return 0;}n->items=v;n->items[n->count++]=x;}if(P.error[0]){if(e&&cap){strncpy(e,P.error,cap-1);e[cap-1]=0;}gml_ast_free(n);return 0;}*out=n;return 1;}
void gml_ast_free(gml_ast*n){if(!n)return;free(n->text);if(n->left)gml_ast_free(n->left);if(n->right)gml_ast_free(n->right);for(size_t i=0;i<n->count;i++)gml_ast_free(n->items[i]);free(n->items);free(n);}
const char*gml_token_name(gml_token_kind k){switch(k){case GML_T_EOF:return"eof";case GML_T_NUMBER:return"number";case GML_T_STRING:return"string";case GML_T_IDENT:return"ident";case GML_T_PLUS:return"+";case GML_T_MINUS:return"-";case GML_T_STAR:return"*";case GML_T_SLASH:return"/";case GML_T_ASSIGN:return"=";default:return"token";}}
